# The live program's link word. Owner decision 2026-10-29: branded links read
# gorefer.in/zerodha/r/{client_id} and gorefer.in/zerodha/open, alongside the
# unchanged bare /r/ and /open links. Seeded as DATA here (and in seed_program) so
# no partner-named route exists in code.
SEEDED_PROGRAM_NAME = "Zerodha"
SEEDED_URL_PREFIX = "zerodha"


def seed_url_prefix(apps, schema_editor):
    """Give each tenant's existing seeded program its link word — at most one per
    tenant, so the per-tenant unique constraint added next can always install."""
    ReferralProgram = apps.get_model("referrals", "ReferralProgram")
    seen_tenants = set()
    for program in ReferralProgram.objects.filter(
        name__iexact=SEEDED_PROGRAM_NAME, url_prefix=""
    ).order_by("id"):
        if program.tenant_id in seen_tenants:
            continue
        seen_tenants.add(program.tenant_id)
        program.url_prefix = SEEDED_URL_PREFIX
        program.save(update_fields=["url_prefix"])


